import os
import json
import hashlib
import time
from datetime import datetime
from database import get_db_connection

# Path to contract deployment data generated by Hardhat
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
CONTRACT_DATA_PATH = os.path.join(BASE_DIR, "contract_data.json")

# Default Hardhat local development credentials (well-known default devnet account #0)
DEFAULT_HARDHAT_RPC = "http://127.0.0.1:8545"
DEFAULT_HARDHAT_ACCOUNT = "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266"
DEFAULT_HARDHAT_KEY = "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80"

def compute_report_hash(content: str) -> str:
    """
    Computes a deterministic cryptographic SHA-256 hash of report markdown content.
    Returns 0x-prefixed 64-character hex string (32 bytes).
    """
    normalized = content.strip().encode("utf-8")
    digest = hashlib.sha256(normalized).hexdigest()
    return f"0x{digest}"

def load_contract_data():
    """Loads contract ABI and address from deployment artifact if present."""
    if os.path.exists(CONTRACT_DATA_PATH):
        try:
            with open(CONTRACT_DATA_PATH, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass
    return None

def get_web3_connection():
    """
    Attempts to establish connection to an Ethereum node (Hardhat localhost or Sepolia).
    Returns (w3, contract, network_name) or (None, None, 'offline') if not reachable.
    """
    try:
        from web3 import Web3
    except ImportError:
        return None, None, "offline"

    rpc_url = os.getenv("BLOCKCHAIN_RPC_URL") or os.getenv("BLOCKCHAIN_PROVIDER_URL") or DEFAULT_HARDHAT_RPC
    w3 = Web3(Web3.HTTPProvider(rpc_url, request_kwargs={"timeout": 2}))

    if not w3.is_connected():
        return None, None, "offline"

    contract_data = load_contract_data()
    contract_address = os.getenv("BLOCKCHAIN_CONTRACT_ADDRESS") or os.getenv("CONTRACT_ADDRESS")
    abi = None

    if contract_data:
        contract_address = contract_address or contract_data.get("contract_address")
        abi = contract_data.get("abi")

    network_name = "Sepolia Testnet" if "sepolia" in rpc_url.lower() else "Hardhat Local EVM (31337)"

    contract = None
    if contract_address and abi:
        try:
            checksum_address = w3.to_checksum_address(contract_address)
            contract = w3.eth.contract(address=checksum_address, abi=abi)
        except Exception as e:
            print("Warning: Could not bind smart contract:", e)

    return w3, contract, network_name

def record_report_on_chain(report_id: int, content: str) -> dict:
    """
    Anchors report cryptographic hash to the blockchain smart contract.
    If the local EVM node is offline, records to the cryptographic devnet ledger fallback.
    """
    report_hash = compute_report_hash(content)
    w3, contract, network_name = get_web3_connection()

    # Case 1: Live Ethereum node with deployed smart contract
    if w3 and contract:
        try:
            private_key = os.getenv("BLOCKCHAIN_PRIVATE_KEY", DEFAULT_HARDHAT_KEY)
            account = w3.eth.account.from_key(private_key)

            # Convert hex hash to bytes32
            hash_bytes = bytes.fromhex(report_hash[2:])

            nonce = w3.eth.get_transaction_count(account.address)
            gas_price = w3.eth.gas_price

            tx = contract.functions.recordReport(int(report_id), hash_bytes).build_transaction({
                "from": account.address,
                "nonce": nonce,
                "gasPrice": gas_price,
            })

            # Estimate gas safely
            try:
                gas_est = w3.eth.estimate_gas(tx)
                tx["gas"] = int(gas_est * 1.2)
            except Exception:
                tx["gas"] = 150000

            signed_tx = w3.eth.account.sign_transaction(tx, private_key=private_key)
            tx_hash_bytes = w3.eth.send_raw_transaction(signed_tx.raw_transaction)
            tx_receipt = w3.eth.wait_for_transaction_receipt(tx_hash_bytes, timeout=10)

            tx_hash_hex = tx_receipt.transactionHash.hex()
            block_number = tx_receipt.blockNumber

            # Also mirror to local ledger for instant offline redundancy
            conn = get_db_connection()
            conn.execute(
                "INSERT OR REPLACE INTO blockchain_ledger (report_id, report_hash, tx_hash, block_number, network) VALUES (?, ?, ?, ?, ?)",
                (report_id, report_hash, tx_hash_hex, block_number, network_name)
            )
            conn.commit()
            conn.close()

            return {
                "report_hash": report_hash,
                "tx_hash": tx_hash_hex,
                "block_number": block_number,
                "network": network_name,
                "mode": "on-chain",
                "contract_address": contract.address
            }
        except Exception as e:
            print("Blockchain transaction error (falling back to cryptographic ledger):", e)

    # Case 2: Cryptographic Devnet Ledger Fallback (zero-friction college demo mode)
    conn = get_db_connection()
    timestamp_str = datetime.utcnow().isoformat()
    # Deterministic cryptographic mock tx hash based on sha256
    tx_seed = f"tx:{report_id}:{report_hash}:{timestamp_str}"
    simulated_tx_hash = f"0x{hashlib.sha256(tx_seed.encode()).hexdigest()}"

    # Get sequential block number
    row = conn.execute("SELECT MAX(block_number) as max_blk FROM blockchain_ledger").fetchone()
    current_blk = (row["max_blk"] or 1000) + 1
    fallback_network = "Local Blockchain / Devnet Anchor"

    conn.execute(
        "INSERT OR REPLACE INTO blockchain_ledger (report_id, report_hash, tx_hash, block_number, network) VALUES (?, ?, ?, ?, ?)",
        (report_id, report_hash, simulated_tx_hash, current_blk, fallback_network)
    )
    conn.commit()
    conn.close()

    contract_data = load_contract_data()
    contract_addr = contract_data.get("contract_address") if contract_data else "0x5FbDB2315678afecb367f032d93F642f64180aa3"

    return {
        "report_hash": report_hash,
        "tx_hash": simulated_tx_hash,
        "block_number": current_blk,
        "network": fallback_network,
        "mode": "devnet-ledger",
        "contract_address": contract_addr
    }

def verify_report_on_chain(report_id: int, current_content: str) -> dict:
    """
    Verifies report integrity by recomputing the SHA-256 hash of current_content
    and checking against the blockchain smart contract record (or cryptographic ledger).
    """
    computed_hash = compute_report_hash(current_content)
    w3, contract, network_name = get_web3_connection()

    on_chain_hash = None
    block_number = None
    tx_hash = None
    network = network_name
    timestamp = None
    exists_on_chain = False
    verification_source = "None"
    is_live_contract_verified = False

    # 1. Attempt smart contract check if live EVM node is reachable
    if w3 and contract:
        try:
            hash_bytes, block_time, blk_num, exists = contract.functions.getReport(int(report_id)).call()
            if exists and hash_bytes != bytes(32):
                on_chain_hash = f"0x{hash_bytes.hex()}"
                block_number = blk_num
                timestamp = datetime.utcfromtimestamp(block_time).isoformat() if block_time else None
                exists_on_chain = True
                is_live_contract_verified = True
                verification_source = f"Live EVM Smart Contract ({contract.address[:10]}...)"
        except Exception as e:
            print("Web3 contract call error:", e)

    # 2. If node is offline or report was anchored in local ledger, check SQLite ledger
    if not on_chain_hash:
        conn = get_db_connection()
        ledger_entry = conn.execute("SELECT * FROM blockchain_ledger WHERE report_id = ?", (report_id,)).fetchone()
        report_entry = conn.execute("SELECT * FROM reports WHERE id = ?", (report_id,)).fetchone()
        conn.close()

        if ledger_entry:
            on_chain_hash = ledger_entry["report_hash"]
            tx_hash = ledger_entry["tx_hash"]
            block_number = ledger_entry["block_number"]
            network = ledger_entry["network"] or "Cryptographic Devnet Ledger"
            timestamp = ledger_entry["timestamp"]
            exists_on_chain = True
            verification_source = "Local Cryptographic Ledger (Node Offline)"
        elif report_entry and report_entry["report_hash"]:
            on_chain_hash = report_entry["report_hash"]
            tx_hash = report_entry["blockchain_tx_id"]
            block_number = report_entry["block_number"]
            network = report_entry["network"] or "Cryptographic Devnet Ledger"
            timestamp = report_entry["timestamp"]
            exists_on_chain = True
            verification_source = "Database Audit Record"

    if not exists_on_chain or not on_chain_hash:
        return {
            "verified": False,
            "status": "UNREGISTERED",
            "message": "Report has not been anchored to the blockchain yet.",
            "verification_source": "None",
            "computed_hash": computed_hash,
            "on_chain_hash": None,
            "tx_hash": None,
            "block_number": None,
            "network": network,
            "timestamp": None
        }

    # Cryptographic integrity comparison
    is_valid = (computed_hash.lower() == on_chain_hash.lower())

    if is_valid:
        status = "VERIFIED"
        if is_live_contract_verified:
            message = f"Report integrity verified on-chain! Cryptographic SHA-256 matches the immutable Solidity Smart Contract record ({verification_source}). No modifications detected."
        else:
            message = "Report integrity verified! Cryptographic SHA-256 hash matches the immutable ledger record. (Live EVM node currently offline; verified via local cryptographic fallback)."
    else:
        status = "TAMPERED"
        message = "SECURITY ALERT: Report tampering detected! The report content in the database does NOT match the immutable hash recorded on the blockchain ledger."

    return {
        "verified": is_valid,
        "status": status,
        "message": message,
        "verification_source": verification_source,
        "computed_hash": computed_hash,
        "on_chain_hash": on_chain_hash,
        "tx_hash": tx_hash,
        "block_number": block_number,
        "network": network,
        "timestamp": timestamp
    }

def get_blockchain_status() -> dict:
    """Returns current blockchain connection diagnostic info with honest mode indicator."""
    w3, contract, network_name = get_web3_connection()
    contract_data = load_contract_data()
    env_contract = os.getenv("BLOCKCHAIN_CONTRACT_ADDRESS") or os.getenv("CONTRACT_ADDRESS")
    contract_address = contract.address if contract else (env_contract or (contract_data.get("contract_address") if contract_data else "0x5FbDB2315678afecb367f032d93F642f64180aa3"))

    conn = get_db_connection()
    try:
        total_anchored = conn.execute("SELECT COUNT(*) FROM blockchain_ledger").fetchone()[0]
    except Exception:
        from database import init_db
        init_db()
        try:
            total_anchored = conn.execute("SELECT COUNT(*) FROM blockchain_ledger").fetchone()[0]
        except Exception:
            total_anchored = 0
    conn.close()

    if w3 and w3.is_connected():
        try:
            latest_block = w3.eth.block_number
        except Exception:
            latest_block = "Unknown"
        return {
            "status": "connected",
            "mode": "live_smart_contract",
            "mode_label": "Live EVM Smart Contract (Mining Active)",
            "provider": "EVM Node (Web3.py JSON-RPC)",
            "network": network_name,
            "contract_address": contract_address,
            "latest_block": latest_block,
            "total_anchored_reports": total_anchored,
            "is_live_node": True,
            "tip": "Smart contract is actively listening and mining on-chain blocks."
        }
    else:
        return {
            "status": "active_devnet",
            "mode": "cryptographic_ledger_fallback",
            "mode_label": "Cryptographic Ledger (Local SHA-256 Fallback)",
            "provider": "Local Cryptographic Ledger (Solidity Compatible)",
            "network": "Local Devnet Anchor (Node Offline)",
            "contract_address": contract_address,
            "latest_block": 1000 + total_anchored,
            "total_anchored_reports": total_anchored,
            "is_live_node": False,
            "tip": "Start a live Hardhat node via 'npx hardhat node' in the blockchain/ directory to switch to live EVM mining."
        }
